  "check_code": "import re
import shutil
import sqlite3
from datetime import datetime, timezone
from pathlib import Path

PLAN_ID = "TCP-RQ-2025-001-A"
ASSIGNMENT_ID = "TCWA-RQ-A-001"
TARGET_CHECK = "TCRC-RQ-A-001-COR"


def _db(ws: Path) -> Path:
    return Path(ws).parent / "system" / "teamcenter_quality_planning" / "state.db"


def _baseline_db(ws: Path) -> Path:
    return Path(ws).parent / "system" / "teamcenter_quality_planning" / "state.db.pinned_backup"


def _conn(path: Path):
    con = sqlite3.connect(path)
    con.row_factory = sqlite3.Row
    return con


def _norm(value) -> str:
    return re.sub(r"[^a-z0-9]+", " ", str(value or "").lower()).strip()


def _valid_utc(value) -> bool:
    if not isinstance(value, str) or not value.strip():
        return False
    try:
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
        return parsed.tzinfo is not None and parsed.astimezone(timezone.utc) == parsed.astimezone(timezone.utc)
    except ValueError:
        return False


def check_corrosion_check_post_state(ws):
    con = _conn(_db(ws))
    try:
        row = con.execute(
            "SELECT * FROM release_checks WHERE release_check_id=? AND plan_id=? AND witness_assignment_id=? AND check_type=?",
            (TARGET_CHECK, PLAN_ID, ASSIGNMENT_ID, "CORROSION"),
        ).fetchone()
    finally:
        con.close()
    if row is None:
        return {"score": 0, "detail": "Target corrosion release-check row is missing."}
    errors = []
    if row["required_flag"] != 1:
        errors.append("required flag is not 1")
    if row["result_status"] != "PASS":
        errors.append("result status is not PASS")
    text = _norm(row["result_value_text"])
    required_groups = [
        ("pp 001", "register sp 001", "specimen identity"),
        ("480 0 h", "480 0", "480 hours"),
        ("astm b117", "neutral salt spray"),
        ("0 00 red rust", "0 0 red rust", "red rust area 0 00", "red rust area 0 0", "red rust 0 00", "red rust 0 0", "no red rust"),
        ("custody", "priya n sethi", "elliot j marston", "daniel r hensley"),
    ]
    for group in required_groups:
        if not any(_norm(option) in text for option in group):
            errors.append("result text lacks " + "/".join(group))
    if not _valid_utc(row["verified_utc"]):
        errors.append("verified UTC timestamp is invalid or missing")
    if row["verified_by_person_id"] != "PERSON-LAB-SEA-006":
        errors.append("verification person is not the corrosion lab verifier")
    return {"score": 0 if errors else 1, "detail": "; ".join(errors) if errors else "Target corrosion check has the required PASS evidence and metadata."}


def check_protected_records_unchanged(ws):
    current = _conn(_db(ws))
    baseline_path = _baseline_db(ws)
    if not baseline_path.exists():
        return {"score": 0, "detail": "Pinned baseline database is unavailable."}
    baseline = _conn(baseline_path)
    try:
        errors = []
        for table, where, params in (
            ("controlled_plans", "plan_id=?", (PLAN_ID,)),
            ("witness_assignments", "witness_assignment_id=?", (ASSIGNMENT_ID,)),
        ):
            current_row = current.execute(f"SELECT * FROM {table} WHERE {where}", params).fetchone()
            baseline_row = baseline.execute(f"SELECT * FROM {table} WHERE {where}", params).fetchone()
            if current_row is None or baseline_row is None or tuple(current_row) != tuple(baseline_row):
                errors.append(table + " target record changed")
        current_checks = {
            r["release_check_id"]: dict(r)
            for r in current.execute(
                "SELECT * FROM release_checks WHERE witness_assignment_id=?", (ASSIGNMENT_ID,)
            )
        }
        baseline_checks = {
            r["release_check_id"]: dict(r)
            for r in baseline.execute(
                "SELECT * FROM release_checks WHERE witness_assignment_id=?", (ASSIGNMENT_ID,)
            )
        }
        if set(current_checks) != set(baseline_checks):
            errors.append("target-assignment release-check membership changed")
        for check_id, expected in baseline_checks.items():
            actual = current_checks.get(check_id)
            if actual is None:
                continue
            if check_id == TARGET_CHECK:
                for key in ("release_check_id", "plan_id", "witness_assignment_id", "check_type", "required_flag"):
                    if actual[key] != expected[key]:
                        errors.append(f"target immutable field changed: {key}")
            elif actual != expected:
                errors.append(f"non-target release check changed: {check_id}")
    finally:
        current.close()
        baseline.close()
    return {"score": 0 if errors else 1, "detail": "; ".join(errors) if errors else "Protected records and non-target checks are unchanged."}
